import { useMemo, useState } from 'react'
import { useLiveQuery } from 'dexie-react-hooks'
import { differenceInCalendarDays, format, parseISO, startOfMonth } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Scale, Sheet } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, setVisibility, softDelete } from '@/db/db'
import { estimate, SHARE_LEVELS, type CycleShareLevel } from './cycleMath'
import { PHASES, phasesFor, regularity, shapeFrom, timeline, todayIn, type PhaseId } from './phases'
import CycleCalendar, { marksFor } from './CycleCalendar'
import DaySheet from './DaySheet'
import { readDays } from './dayStore'
import { Dictate } from '@/features/voice/Dictate'
import type { CycleLog } from '@/types/domain'
import { useI18n, useT } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import './cycle.css'

const SYMPTOMS = ['kram', 'pusing', 'mual', 'nyeri punggung', 'jerawat', 'kembung', 'susah tidur', 'nafsu makan naik']

type Tab = 'calendar' | 'today' | 'history' | 'learn' | 'share'
const TABS: readonly Tab[] = ['calendar', 'today', 'history', 'learn', 'share']

/**
 * Catatan siklus (CAL-05/06, blueprint 05 §8).
 *
 * Owned by the person whose body it is. Private by default, shared only at the
 * level they choose, revocable in one tap. Nothing here explains anyone's mood.
 *
 * The module now covers what a cycle app is actually opened for — a month
 * calendar, a day to log into, the four phases and what each is doing — but the
 * medical line has not moved: every predicted date is a range, every range
 * states how much history it rests on, and nothing here is contraception or a
 * diagnosis.
 */
export default function Cycle() {
  const { t, locale } = useI18n()
  const { profile, partner } = useSession()
  const me = profile?.id
  const [tab, setTab] = useState<Tab>('calendar')
  const [open, setOpen] = useState(false)
  const [month, setMonth] = useState(() => startOfMonth(new Date()))
  const [selected, setSelected] = useState(() => format(new Date(), 'yyyy-MM-dd'))
  const [dayOpen, setDayOpen] = useState(false)

  const logs = useOwned<CycleLog>('cycles', me, (a, b) => b.startDate.localeCompare(a.startDate))
  const days = useLiveQuery(async () => (me ? readDays(me) : []), [me])
  const shareLevel = useLiveQuery(
    async () => ((await db.settings.get('cycle.shareLevel'))?.value as CycleShareLevel) ?? 'none',
    [],
  )

  const starts = useMemo(() => (logs ?? []).map((l) => l.startDate), [logs])
  const shape = useMemo(
    () =>
      shapeFrom(
        starts,
        (logs ?? []).map((l) => l.durationDays ?? 0).filter(Boolean),
      ),
    [starts, logs],
  )
  const now = useMemo(() => todayIn(starts, shape), [starts, shape])
  const reg = useMemo(() => regularity(starts), [starts])
  const marks = useMemo(
    () => marksFor(timeline(starts, shape, 4), new Set((days ?? []).map((d) => d.date))),
    [starts, shape, days],
  )

  if (!profile || !me) return null

  const est = estimate(starts)
  const level = shareLevel ?? 'none'
  const selectedDay = (days ?? []).find((d) => d.date === selected)

  async function setLevel(next: CycleShareLevel) {
    await db.settings.put({ key: 'cycle.shareLevel', value: next })
    // Revoking the level closes every already-shared log too — otherwise
    // "berhenti berbagi" would only stop new entries.
    for (const l of logs ?? []) {
      const want = next === 'full' ? 'shared' : 'private'
      if (l.visibility !== want) await setVisibility('cycles', l.id, me!, want)
    }
  }

  /**
   * One tap to say the period arrived.
   *
   * Every estimate on every tab hangs off these dates, so this had to be the
   * cheapest action in the module — not a form.
   */
  async function startPeriodToday() {
    const today = format(new Date(), 'yyyy-MM-dd')
    if (starts.includes(today)) return
    await db.cycles.add({
      ...newEnvelope(me!, 'C4_health', level === 'full' ? { visibility: 'shared' } : {}),
      kind: 'cycle',
      startDate: today,
      symptoms: [],
    } as never)
  }

  return (
    <div className="stack">
      <h1>{t('cyc.title')}</h1>
      <p className="disclaimer">{t('cyc.disclaimer')}</p>

      <div className="segmented" role="group" aria-label={t('cyc.title')} style={{ flexWrap: 'wrap' }}>
        {TABS.map((id) => (
          <button key={id} type="button" aria-pressed={tab === id} onClick={() => setTab(id)}>
            {t(`cyc2.tab.${id}`)}
          </button>
        ))}
      </div>

      {(tab === 'calendar' || tab === 'today') && (
        <section className="cycnow">
          {now.cycleDay === null ? (
            <>
              <p className="card__hint">{t('cyc2.today.noData')}</p>
              <button
                type="button"
                className="btn"
                style={{ marginTop: 'var(--space-3)' }}
                onClick={() => void startPeriodToday()}
              >
                <Icon name="plus" size={18} />
                {t('cyc2.cal.startPeriod')}
              </button>
            </>
          ) : (
            <>
              <b className="cycnow__day">{t('cyc2.today.day', { n: now.cycleDay })}</b>
              {now.phase && (
                <span className="cycnow__phase">
                  <Icon name="cycle" size={15} />
                  {t('cyc2.today.phase', { phase: t(`cyc2.phase.${now.phase}`) })}
                </span>
              )}
              <p className="cycnow__meta">
                {now.daysToNext !== null && now.daysToNext >= 0
                  ? t('cyc2.today.toNext', { n: now.daysToNext })
                  : t('cyc2.today.late', { n: Math.abs(now.daysToNext ?? 0) })}
                {est.nextStartRange && (
                  <>
                    {' · '}
                    {t('cyc2.today.window', {
                      from: fmtDate(est.nextStartRange[0], 'd MMM', locale),
                      to: fmtDate(est.nextStartRange[1], 'd MMM', locale),
                    })}
                  </>
                )}
              </p>
              <p className="cycnow__meta">
                {t(`cyc2.today.confidence.${est.confidence}`)} ·{' '}
                {t('cyc2.hist.cycles', { n: est.basedOnCycles })}
              </p>
              {now.daysToNext !== null && now.daysToNext < 0 && (
                <p className="disclaimer" style={{ marginTop: 'var(--space-3)' }}>
                  {t('cyc2.today.lateHint')}
                </p>
              )}
            </>
          )}
        </section>
      )}

      {tab === 'calendar' && (
        <Card title={t('cyc2.cal.title')} icon="calendar" hint={t('cyc2.cal.hint')}>
          <CycleCalendar
            month={month}
            onMonth={setMonth}
            marks={marks}
            selected={selected}
            onSelect={(d) => {
              setSelected(d)
              setDayOpen(true)
            }}
          />
          <p className="card__hint" style={{ marginTop: 'var(--space-3)' }}>
            {starts.length === 0 ? t('cyc2.cal.needFirst') : t('cyc2.today.confidenceHint')}
          </p>
        </Card>
      )}

      {tab === 'today' && (
        <>
          <Card title={t('cyc2.tab.today')} icon="cycle">
            <div className="stack stack--tight">
              <button
                type="button"
                className="btn btn--block"
                onClick={() => {
                  setSelected(format(new Date(), 'yyyy-MM-dd'))
                  setDayOpen(true)
                }}
              >
                <Icon name="plus" size={18} />
                {t('cyc2.day.save')}
              </button>
              <button type="button" className="btn btn--ghost btn--block" onClick={() => void startPeriodToday()}>
                <Icon name="cycle" size={18} />
                {t('cyc2.cal.startPeriod')}
              </button>
              <button type="button" className="btn btn--ghost btn--block" onClick={() => setOpen(true)}>
                <Icon name="plus" size={18} /> {t('cyc.record')}
              </button>
            </div>
          </Card>

          {now.phase && <PhaseCard id={now.phase} spanLabel={null} />}
        </>
      )}

      {tab === 'history' && (
        <>
          <Card title={t('cyc2.hist.title')} icon="calendar">
            {reg.cycles === 0 ? (
              <p className="card__hint">{t('cyc2.hist.none')}</p>
            ) : (
              <div className="stack stack--tight">
                <dl className="sync__meta">
                  <dt>{t('cyc2.hist.avg')}</dt>
                  <dd>{t('cyc2.hist.days', { n: shape.length })}</dd>
                  <dt>{t('cyc2.hist.period')}</dt>
                  <dd>{t('cyc2.hist.days', { n: shape.periodDays })}</dd>
                  {reg.range && (
                    <>
                      <dt>{t('cyc2.hist.spread')}</dt>
                      <dd>
                        {reg.range[0]}–{reg.range[1]} ({t('cyc2.hist.days', { n: reg.spread ?? 0 })})
                      </dd>
                    </>
                  )}
                </dl>
                <p className="card__hint">{t(`cyc2.hist.band.${reg.band}`, { n: reg.spread ?? 0 })}</p>
                <CycleBars starts={starts} />
              </div>
            )}
          </Card>

          <Card title={t('cyc.history')} icon="cycle">
            {(logs ?? []).length === 0 ? (
              <EmptyState icon="cycle" title={t('cyc2.hist.none')} />
            ) : (
              <ul className="list">
                {(logs ?? []).map((l, i) => {
                  // `logs` is newest first, so the *previous* row is the later
                  // cycle — that gap is this cycle's length.
                  const later = (logs ?? [])[i - 1]
                  const len = later
                    ? differenceInCalendarDays(parseISO(later.startDate), parseISO(l.startDate))
                    : null
                  return (
                    <li key={l.id} className="list__item">
                      <Icon name="cycle" size={18} />
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14 }}>
                          {len === null
                            ? `${fmtDate(l.startDate, 'd MMMM yyyy', locale)} · ${t('cyc2.hist.ongoing')}`
                            : t('cyc2.hist.cycleRow', {
                                date: fmtDate(l.startDate, 'd MMM yyyy', locale),
                                n: len,
                              })}
                        </strong>
                        <span className="card__hint">
                          {l.durationDays ? t('cyc.days', { n: l.durationDays }) : t('cyc.noDuration')}
                        </span>
                        {l.supportPreference && <span className="card__hint">“{l.supportPreference}”</span>}
                      </span>
                      <button
                        className="btn btn--ghost btn--sm btn--icon"
                        onClick={() => softDelete('cycles', l.id, me)}
                      >
                        <Icon name="close" size={16} label={t('cyc.deleteEntry')} />
                      </button>
                    </li>
                  )
                })}
              </ul>
            )}
          </Card>
        </>
      )}

      {tab === 'learn' && (
        <>
          <Card title={t('cyc2.learn.title')} icon="info" hint={t('cyc2.learn.hint')}>
            <div className="stack stack--tight">
              {PHASES.map((id) => {
                // When there is history, each phase carries the day numbers it
                // actually spans for *this* person rather than textbook ones.
                const span = starts.length
                  ? phasesFor(starts[starts.length - 1]!, shape).find((p) => p.id === id)
                  : undefined
                return (
                  <PhaseCard
                    key={id}
                    id={id}
                    spanLabel={span ? `${t('cyc2.cal.dayLabel', { n: span.dayFrom })}–${span.dayTo}` : null}
                  />
                )
              })}
            </div>
          </Card>

          <Card title={t('cyc2.learn.fertileTitle')} icon="info">
            <div className="stack stack--tight">
              <p>{t('cyc2.learn.fertileBody')}</p>
              <p className="banner banner--warn">{t('cyc2.learn.fertileWarn')}</p>
            </div>
          </Card>

          <Card title={t('cyc2.learn.signsTitle')} icon="checkin">
            <p>{t('cyc2.learn.signsBody')}</p>
          </Card>

          <Card title={t('cyc2.learn.trackTitle')} icon="cycle">
            <p>{t('cyc2.learn.trackBody')}</p>
          </Card>

          <Card title={t('cyc2.learn.seeDoctorTitle')} icon="health">
            <div className="stack stack--tight">
              <p>{t('cyc2.learn.seeDoctorBody')}</p>
              <p className="disclaimer">{t('cyc2.learn.sourceNote')}</p>
            </div>
          </Card>
        </>
      )}

      {tab === 'share' && (
        <>
          <Card title={t('cyc2.share.title')} icon="consent" hint={t('cyc2.share.body')}>
            <p className="disclaimer">{t('cyc2.share.neverShared')}</p>
          </Card>
          {partner && (
            <Card
              title={t('cyc.sharing')}
              icon="consent"
              hint={t('cyc.sharingNow', { level: t(`share.${level}` as const).toLowerCase() })}
            >
              <div className="choices" role="radiogroup" aria-label={t('cyc.sharingGroup')}>
                {SHARE_LEVELS.map((lvl) => (
                  <button
                    key={lvl}
                    type="button"
                    role="radio"
                    aria-checked={level === lvl}
                    className="choice"
                    onClick={() => setLevel(lvl)}
                  >
                    <span className="stack stack--tight">
                      <span className="choice__title">{t(`share.${lvl}` as const)}</span>
                      <span className="choice__desc">{t(`share.${lvl}.desc` as const)}</span>
                    </span>
                  </button>
                ))}
              </div>
              {level !== 'none' && (
                <button
                  className="btn btn--danger btn--block"
                  style={{ marginTop: 'var(--space-3)' }}
                  onClick={() => setLevel('none')}
                >
                  <Icon name="private" size={18} /> {t('cyc.stopSharing')}
                </button>
              )}
            </Card>
          )}
        </>
      )}

      <DaySheet
        open={dayOpen}
        onClose={() => setDayOpen(false)}
        me={me}
        date={selected}
        existing={selectedDay}
      />
      <NewCycleSheet open={open} onClose={() => setOpen(false)} me={me} shareFull={level === 'full'} />
    </div>
  )
}

/** One phase, explained. The same component on the Today tab and in the guide. */
function PhaseCard({ id, spanLabel }: { id: PhaseId; spanLabel: string | null }) {
  const { t } = useI18n()
  return (
    <article className="phasecard">
      <div className="phasecard__top">
        <span className="phasecard__name">{t(`cyc2.phase.${id}`)}</span>
        {spanLabel && <span className="phasecard__days">{spanLabel}</span>}
      </div>
      <p className="phasecard__short">{t(`cyc2.phase.${id}.short`)}</p>
      <p>{t(`cyc2.phase.${id}.body`)}</p>
      <p>{t(`cyc2.phase.${id}.common`)}</p>
      <p className="phasecard__fact">{t(`cyc2.phase.${id}.fact`)}</p>
    </article>
  )
}

/**
 * Cycle lengths as bars.
 *
 * No axis, no target line, no "ideal" marker: this is a picture of what
 * happened, and a reference line would turn it into a score.
 */
function CycleBars({ starts }: { starts: string[] }) {
  const { t } = useI18n()
  const lengths = useMemo(() => {
    const sorted = [...new Set(starts)].sort()
    const out: number[] = []
    for (let i = 1; i < sorted.length; i++) {
      const g = differenceInCalendarDays(parseISO(sorted[i]!), parseISO(sorted[i - 1]!))
      if (g >= 15 && g <= 60) out.push(g)
    }
    return out.slice(-12)
  }, [starts])
  if (lengths.length < 2) return null
  const peak = Math.max(...lengths)
  return (
    <figure style={{ margin: 0 }}>
      <figcaption className="card__hint">{t('cyc2.hist.chartLabel')}</figcaption>
      <div
        className="cycbars"
        role="img"
        aria-label={`${t('cyc2.hist.chartLabel')}: ${lengths.join(', ')}`}
      >
        {lengths.map((n, i) => (
          <span
            key={i}
            className={`cycbars__bar ${n >= peak ? 'cycbars__bar--long' : ''}`}
            style={{ height: `${Math.max(12, (n / peak) * 100)}%` }}
          />
        ))}
      </div>
    </figure>
  )
}

function NewCycleSheet({
  open,
  onClose,
  me,
  shareFull,
}: {
  open: boolean
  onClose: () => void
  me: string
  shareFull: boolean
}) {
  const t = useT()
  const [start, setStart] = useState(format(new Date(), 'yyyy-MM-dd'))
  const [duration, setDuration] = useState('')
  const [symptoms, setSymptoms] = useState<string[]>([])
  const [energy, setEnergy] = useState<1 | 2 | 3 | 4 | 5>()
  const [pain, setPain] = useState<1 | 2 | 3 | 4 | 5>()
  const [support, setSupport] = useState('')

  async function save() {
    await db.cycles.add({
      ...newEnvelope(me, 'C4_health', shareFull ? { visibility: 'shared' } : {}),
      kind: 'cycle',
      startDate: start,
      ...(duration ? { durationDays: Number(duration) } : {}),
      symptoms,
      ...(energy ? { energy } : {}),
      ...(pain ? { pain } : {}),
      ...(support.trim() ? { supportPreference: support.trim() } : {}),
    } as never)
    setSymptoms([])
    setDuration('')
    setSupport('')
    setEnergy(undefined)
    setPain(undefined)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('cyc.sheet')}>
      <div className="stack">
        <Field label={t('cyc.firstDay')}>
          {(p) => <input {...p} type="date" value={start} onChange={(e) => setStart(e.target.value)} />}
        </Field>
        <Field label={t('cyc.duration')} hint={t('cyc.durationHint')}>
          {(p) => (
            <input {...p} type="number" min="1" max="15" value={duration} onChange={(e) => setDuration(e.target.value)} />
          )}
        </Field>

        <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
          <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('cyc.symptoms')}</legend>
          <div className="row" style={{ gap: 'var(--space-2)' }}>
            {SYMPTOMS.map((s) => {
              const on = symptoms.includes(s)
              return (
                <button
                  key={s}
                  type="button"
                  aria-pressed={on}
                  className={`chip ${on ? 'chip--primary' : ''}`}
                  style={{ cursor: 'pointer', minHeight: 34 }}
                  onClick={() => setSymptoms((c) => (on ? c.filter((x) => x !== s) : [...c, s]))}
                >
                  {s}
                </button>
              )
            })}
          </div>
        </fieldset>

        <Scale legend={t('cyc.energy')} value={energy} onChange={setEnergy} lowLabel={t('cyc.energyLow')} highLabel={t('cyc.energyHigh')} />
        <Scale legend={t('cyc.pain')} value={pain} onChange={setPain} lowLabel={t('cyc.painLow')} highLabel={t('cyc.painHigh')} />

        <Field label={t('cyc.support')} hint={t('cyc.supportHint')}>
          {(p) => (
            <textarea
              {...p}
              value={support}
              placeholder={t('cyc.supportPlaceholder')}
              onChange={(e) => setSupport(e.target.value)}
            />
          )}
        </Field>
        <Dictate value={support} onChange={setSupport} label={t('cyc.support')} />

        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
