import { db, logAudit, newEnvelope, readable } from '@/db/db'
import type { CycleDay } from '@/types/domain'

/**
 * Reads and writes for one day of cycle tracking.
 *
 * Two things here are deliberate:
 *
 *   - **One row per date.** A day is re-logged constantly — you note cramps in
 *     the morning and the temperature you forgot at noon — so a write looks the
 *     day up and patches it instead of appending. Otherwise a month of tracking
 *     leaves forty rows for thirty days and every read has to guess which one
 *     is current.
 *   - **Health class, private visibility.** `C4_health` defaults to private in
 *     `DEFAULT_VISIBILITY`, which is what keeps these rows out of a partner's
 *     view unless the owner widens the cycle sharing level on purpose.
 */

export const SYMPTOM_GROUPS: readonly { group: string; ids: readonly string[] }[] = [
  { group: 'badan', ids: ['kram', 'nyeri_punggung', 'payudara_nyeri', 'badan_pegal', 'lemas'] },
  { group: 'perut', ids: ['kembung', 'mual', 'diare', 'sembelit', 'nafsu_makan', 'ngidam'] },
  { group: 'kepala', ids: ['pusing', 'migrain', 'susah_tidur', 'ngantuk'] },
  { group: 'kulit', ids: ['jerawat', 'kulit_berminyak', 'rambut_rontok'] },
]

export const MOODS: readonly string[] = [
  'senang',
  'tenang',
  'biasa',
  'semangat',
  'sensitif',
  'gampang_marah',
  'cemas',
  'sedih',
]

export const FLOWS = ['none', 'spotting', 'light', 'medium', 'heavy'] as const
export const DISCHARGES = ['tidak dicek', 'kering', 'lengket', 'krim', 'bening'] as const
export const OPKS = ['tidak dicek', 'negatif', 'positif'] as const
export const INTIMACIES = ['tidak', 'ya', 'ya_pengaman'] as const

export type DayDraft = Omit<CycleDay, keyof ReturnType<typeof newEnvelope> | 'kind'>

/** Everything the owner may read, newest first. */
export async function readDays(me: string): Promise<CycleDay[]> {
  const rows = await readable<CycleDay>('cycleDays', me)
  return rows.sort((a, b) => b.date.localeCompare(a.date))
}

export function isEmptyDay(d: Partial<CycleDay>): boolean {
  return (
    (!d.flow || d.flow === 'none') &&
    !d.symptoms?.length &&
    !d.mood?.length &&
    (!d.discharge || d.discharge === 'tidak dicek') &&
    d.temperature === undefined &&
    (!d.opk || d.opk === 'tidak dicek') &&
    (!d.intimacy || d.intimacy === 'tidak') &&
    d.energy === undefined &&
    d.pain === undefined &&
    !d.note?.trim()
  )
}

/**
 * Save one day, replacing whatever was there.
 *
 * A day emptied of everything is deleted rather than stored as a row of blanks:
 * an empty row would put a "logged" dot on the calendar for a day the person
 * just cleared.
 */
export async function saveDay(me: string, date: string, body: Partial<CycleDay>): Promise<void> {
  const existing = (await db.table<CycleDay>('cycleDays').where('date').equals(date).toArray()).find(
    (r) => r.ownerProfileId === me && !r.deletedAt,
  )

  if (isEmptyDay(body)) {
    if (existing) {
      await db.table('cycleDays').update(existing.id, { deletedAt: new Date().toISOString() })
      await logAudit({
        actorProfileId: me,
        action: 'delete',
        objectStore: 'cycleDays',
        objectId: existing.id,
        summary: 'catatan harian siklus dihapus',
      })
    }
    return
  }

  if (existing) {
    await db.table('cycleDays').update(existing.id, { ...body, updatedAt: new Date().toISOString() })
    await logAudit({
      actorProfileId: me,
      action: 'update',
      objectStore: 'cycleDays',
      objectId: existing.id,
      // The audit trail records that a day changed, never what was in it.
      summary: 'catatan harian siklus diubah',
    })
    return
  }

  const env = newEnvelope(me, 'C4_health')
  await db.table('cycleDays').put({ ...env, kind: 'cycleDay', date, symptoms: [], ...body })
  await logAudit({
    actorProfileId: me,
    action: 'create',
    objectStore: 'cycleDays',
    objectId: env.id,
    summary: 'catatan harian siklus dibuat',
  })
}
