import { addDays, differenceInCalendarDays, format, parseISO } from 'date-fns'

/**
 * The four phases of a cycle, and where today sits in them — pure, no React,
 * no Dexie, no copy.
 *
 * `cycleMath.ts` already answered "when is the next period, roughly". This
 * answers the question the screen was missing entirely: what is happening now,
 * what comes next, and when. Everything is derived from what the owner logged;
 * nothing here is measured.
 *
 * Three rules hold the whole file together, and they are medical-safety rules,
 * not style:
 *
 *   1. **Every boundary is a range.** A phase that starts on "day 15" is a
 *      textbook, not a person. Ovulation in particular is estimated backwards
 *      from the *next* period because the luteal phase is the steadier half —
 *      and it still gets a multi-day window.
 *   2. **Confidence is stated, and it is capped.** Four logged cycles is not
 *      certainty; the ceiling is `sedang` and there is no level above it.
 *   3. **This is never contraception and never a diagnosis.** No "safe day"
 *      exists in this file, and nothing here labels a body as irregular — the
 *      copy describes spread in days and leaves the conclusion to the person
 *      and, if they want, a professional.
 */

export type PhaseId = 'menstruasi' | 'folikular' | 'ovulasi' | 'luteal'

export const PHASES: readonly PhaseId[] = ['menstruasi', 'folikular', 'ovulasi', 'luteal']

export interface PhaseSpan {
  id: PhaseId
  /** Inclusive `yyyy-MM-dd`. */
  from: string
  to: string
  /** Day numbers within the cycle, 1-based and inclusive. */
  dayFrom: number
  dayTo: number
}

export interface CycleShape {
  /** Cycle length used for the projection. */
  length: number
  /** Bleeding days used for the projection. */
  periodDays: number
  /** Days from ovulation to the next period. The steadier half of the cycle. */
  lutealDays: number
}

/** What a textbook says, used only until the person has logged enough. */
export const DEFAULT_SHAPE: CycleShape = { length: 28, periodDays: 5, lutealDays: 14 }

export interface Today {
  /** 1-based day of the current cycle, or null before the first logged period. */
  cycleDay: number | null
  phase: PhaseId | null
  /** Days until the next expected period. Negative means it is late. */
  daysToNext: number | null
}

/**
 * The shape of a person's cycle, from their own history.
 *
 * Medians rather than means: one 45-day cycle after an illness should not drag
 * every future estimate with it, and a mean is exactly how that happens.
 */
export function shapeFrom(starts: string[], periodLengths: number[] = []): CycleShape {
  const sorted = [...new Set(starts)].sort()
  const gaps: number[] = []
  for (let i = 1; i < sorted.length; i++) {
    const g = differenceInCalendarDays(parseISO(sorted[i]!), parseISO(sorted[i - 1]!))
    // Out-of-range gaps are mistyped dates or a missed month, not cycles.
    if (g >= 15 && g <= 60) gaps.push(g)
  }
  const bleeding = periodLengths.filter((d) => d >= 1 && d <= 14)
  return {
    length: gaps.length ? median(gaps) : DEFAULT_SHAPE.length,
    periodDays: bleeding.length ? median(bleeding) : DEFAULT_SHAPE.periodDays,
    // Held constant on purpose. The luteal phase varies far less than the
    // follicular one, so a *changing* cycle length is modelled as the first
    // half moving — which is what actually happens.
    lutealDays: DEFAULT_SHAPE.lutealDays,
  }
}

function median(xs: number[]): number {
  const s = [...xs].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  return s.length % 2 ? s[mid]! : Math.round((s[mid - 1]! + s[mid]!) / 2)
}

/**
 * The four phases of one cycle that began on `startDate`.
 *
 * Ovulation is placed `lutealDays` before the *end* of the cycle rather than a
 * fixed number of days after its start. On a 34-day cycle the textbook "day 14"
 * would be a week early, which is the single most common way these apps mislead.
 */
export function phasesFor(startDate: string, shape: CycleShape = DEFAULT_SHAPE): PhaseSpan[] {
  const start = parseISO(startDate)
  const len = Math.max(15, Math.min(60, Math.round(shape.length)))
  const bleed = Math.max(1, Math.min(len - 6, Math.round(shape.periodDays)))
  const ovulationDay = Math.max(bleed + 2, len - shape.lutealDays)
  // Two days either side: the egg lives about a day, sperm rather longer, and
  // the estimate itself is soft. This window is the fertile one, and it is
  // deliberately wider than the ovulation "day" people expect.
  const ovFrom = Math.max(bleed + 1, ovulationDay - 2)
  const ovTo = Math.min(len - 1, ovulationDay + 2)

  const span = (id: PhaseId, dayFrom: number, dayTo: number): PhaseSpan => ({
    id,
    dayFrom,
    dayTo,
    from: format(addDays(start, dayFrom - 1), 'yyyy-MM-dd'),
    to: format(addDays(start, dayTo - 1), 'yyyy-MM-dd'),
  })

  const out: PhaseSpan[] = [span('menstruasi', 1, bleed)]
  if (ovFrom > bleed + 1) out.push(span('folikular', bleed + 1, ovFrom - 1))
  out.push(span('ovulasi', ovFrom, ovTo))
  if (ovTo < len) out.push(span('luteal', ovTo + 1, len))
  return out
}

/** Which phase a date falls in, given the cycle it belongs to. */
export function phaseOn(date: string, startDate: string, shape: CycleShape): PhaseId | null {
  const day = differenceInCalendarDays(parseISO(date), parseISO(startDate)) + 1
  if (day < 1) return null
  const spans = phasesFor(startDate, shape)
  return spans.find((s) => day >= s.dayFrom && day <= s.dayTo)?.id ?? null
}

/**
 * Where the person is right now.
 *
 * A cycle that has run past its expected length is *not* rolled over into the
 * next one: a late period is late, and pretending the next cycle already began
 * would hide exactly the thing worth noticing.
 */
export function todayIn(starts: string[], shape: CycleShape, today = new Date()): Today {
  const sorted = [...new Set(starts)].sort()
  const last = sorted[sorted.length - 1]
  if (!last) return { cycleDay: null, phase: null, daysToNext: null }
  const day = differenceInCalendarDays(today, parseISO(last)) + 1
  if (day < 1) return { cycleDay: null, phase: null, daysToNext: null }
  return {
    cycleDay: day,
    phase: phaseOn(format(today, 'yyyy-MM-dd'), last, shape),
    daysToNext: shape.length - day + 1,
  }
}

export interface PredictedCycle {
  startDate: string
  phases: PhaseSpan[]
  /** True once this cycle is projected rather than logged. */
  predicted: boolean
}

/**
 * Logged cycles plus `ahead` projected ones, so a calendar can be paged into
 * next month without the colours simply stopping.
 */
export function timeline(starts: string[], shape: CycleShape, ahead = 3): PredictedCycle[] {
  const sorted = [...new Set(starts)].sort()
  const out: PredictedCycle[] = sorted.map((s) => ({
    startDate: s,
    phases: phasesFor(s, shape),
    predicted: false,
  }))
  const last = sorted[sorted.length - 1]
  if (!last) return out
  let cursor = parseISO(last)
  for (let i = 0; i < ahead; i++) {
    cursor = addDays(cursor, shape.length)
    const d = format(cursor, 'yyyy-MM-dd')
    out.push({ startDate: d, phases: phasesFor(d, shape), predicted: true })
  }
  return out
}

export interface Regularity {
  /** Shortest and longest cycle observed. */
  range: [number, number] | null
  /** Longest minus shortest. The number the copy actually shows. */
  spread: number | null
  cycles: number
  /**
   * A description, never a verdict: `steady` / `varies` / `wide` are about the
   * numbers, and the copy attached to them says so. There is no "irregular"
   * here, because that word is a diagnosis and this file cannot make one.
   */
  band: 'unknown' | 'steady' | 'varies' | 'wide'
}

export function regularity(starts: string[]): Regularity {
  const sorted = [...new Set(starts)].sort()
  const gaps: number[] = []
  for (let i = 1; i < sorted.length; i++) {
    const g = differenceInCalendarDays(parseISO(sorted[i]!), parseISO(sorted[i - 1]!))
    if (g >= 15 && g <= 60) gaps.push(g)
  }
  if (gaps.length < 2) return { range: null, spread: null, cycles: gaps.length, band: 'unknown' }
  const lo = Math.min(...gaps)
  const hi = Math.max(...gaps)
  const spread = hi - lo
  return {
    range: [lo, hi],
    spread,
    cycles: gaps.length,
    // The thresholds are for wording only. Nothing branches on them medically,
    // and the widest band's copy is "worth mentioning to a professional if you
    // want to", not "something is wrong".
    band: spread <= 4 ? 'steady' : spread <= 9 ? 'varies' : 'wide',
  }
}
