import { useEffect, useState } from 'react'
import { Field, Scale, Sheet } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useI18n, type MessageKey } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import { Dictate } from '@/features/voice/Dictate'
import type { CycleDay } from '@/types/domain'
import {
  DISCHARGES,
  FLOWS,
  INTIMACIES,
  MOODS,
  OPKS,
  SYMPTOM_GROUPS,
  saveDay,
} from './dayStore'

/**
 * One day, logged.
 *
 * Everything is optional and everything can be un-set, because the alternative
 * — a form that insists on an answer per field — turns daily tracking into a
 * chore and people stop after a week.
 *
 * Two fields carry a note rather than a label: basal temperature says it
 * confirms ovulation rather than predicting it, and the sex field says plainly
 * that it is never shared. Both are places where a tracker can quietly mislead.
 */
export default function DaySheet({
  open,
  onClose,
  me,
  date,
  existing,
}: {
  open: boolean
  onClose: () => void
  me: string
  date: string
  existing?: CycleDay
}) {
  const { t, locale } = useI18n()
  const [d, setD] = useState<Partial<CycleDay>>({})
  const [saving, setSaving] = useState(false)

  // Reload whenever the sheet points at a different day, so yesterday's answers
  // never bleed into today's form.
  useEffect(() => {
    setD(
      existing
        ? {
            flow: existing.flow,
            symptoms: existing.symptoms ?? [],
            mood: existing.mood ?? [],
            discharge: existing.discharge,
            temperature: existing.temperature,
            opk: existing.opk,
            intimacy: existing.intimacy,
            energy: existing.energy,
            pain: existing.pain,
            note: existing.note,
          }
        : { symptoms: [], mood: [] },
    )
  }, [existing, date, open])

  const toggle = (key: 'symptoms' | 'mood', id: string) =>
    setD((prev) => {
      const list = prev[key] ?? []
      return { ...prev, [key]: list.includes(id) ? list.filter((x) => x !== id) : [...list, id] }
    })

  async function save() {
    if (saving) return
    setSaving(true)
    try {
      await saveDay(me, date, d)
      onClose()
    } finally {
      setSaving(false)
    }
  }

  return (
    <Sheet
      open={open}
      onClose={onClose}
      title={t('cyc2.day.title', { date: fmtDate(date, 'd MMMM yyyy', locale) })}
    >
      <div className="stack stack--tight">
        <p className="cycgroup">{t('cyc2.day.flow')}</p>
        <div className="cycchips" role="group" aria-label={t('cyc2.day.flow')}>
          {FLOWS.map((f) => (
            <button
              key={f}
              type="button"
              className="cycchip"
              aria-pressed={d.flow === f}
              onClick={() => setD({ ...d, flow: d.flow === f ? undefined : f })}
            >
              {t(`cyc2.day.flow.${f}` as MessageKey)}
            </button>
          ))}
        </div>

        <p className="cycgroup">{t('cyc2.day.symptoms')}</p>
        {SYMPTOM_GROUPS.map((g) => (
          <div key={g.group}>
            <p className="card__hint" style={{ marginBottom: 4 }}>
              {t(`cyc2.sym.group.${g.group}` as MessageKey)}
            </p>
            <div className="cycchips">
              {g.ids.map((s) => (
                <button
                  key={s}
                  type="button"
                  className="cycchip"
                  aria-pressed={(d.symptoms ?? []).includes(s)}
                  onClick={() => toggle('symptoms', s)}
                >
                  {t(`cyc2.sym.${s}` as MessageKey)}
                </button>
              ))}
            </div>
          </div>
        ))}

        <p className="cycgroup">{t('cyc2.day.mood')}</p>
        <div className="cycchips" role="group" aria-label={t('cyc2.day.mood')}>
          {MOODS.map((m) => (
            <button
              key={m}
              type="button"
              className="cycchip"
              aria-pressed={(d.mood ?? []).includes(m)}
              onClick={() => toggle('mood', m)}
            >
              {t(`cyc2.mood.${m}` as MessageKey)}
            </button>
          ))}
        </div>

        <p className="cycgroup">{t('cyc2.day.discharge')}</p>
        <p className="card__hint">{t('cyc2.day.discharge.hint')}</p>
        <div className="cycchips" role="group" aria-label={t('cyc2.day.discharge')}>
          {DISCHARGES.map((x) => (
            <button
              key={x}
              type="button"
              className="cycchip"
              aria-pressed={d.discharge === x}
              onClick={() => setD({ ...d, discharge: d.discharge === x ? undefined : x })}
            >
              {t(`cyc2.day.discharge.${x}` as MessageKey)}
            </button>
          ))}
        </div>

        <Field label={t('cyc2.day.temp')} hint={t('cyc2.day.tempHint')}>
          {(p) => (
            <input
              {...p}
              type="number"
              inputMode="decimal"
              step="0.01"
              min="34"
              max="42"
              value={d.temperature ?? ''}
              onChange={(e) =>
                setD({ ...d, temperature: e.target.value === '' ? undefined : Number(e.target.value) })
              }
            />
          )}
        </Field>

        <p className="cycgroup">{t('cyc2.day.opk')}</p>
        <div className="cycchips" role="group" aria-label={t('cyc2.day.opk')}>
          {OPKS.map((x) => (
            <button
              key={x}
              type="button"
              className="cycchip"
              aria-pressed={d.opk === x}
              onClick={() => setD({ ...d, opk: d.opk === x ? undefined : x })}
            >
              {t(`cyc2.day.opk.${x}` as MessageKey)}
            </button>
          ))}
        </div>

        <p className="cycgroup">{t('cyc2.day.intimacy')}</p>
        <p className="card__hint">{t('cyc2.day.intimacyHint')}</p>
        <div className="cycchips" role="group" aria-label={t('cyc2.day.intimacy')}>
          {INTIMACIES.map((x) => (
            <button
              key={x}
              type="button"
              className="cycchip"
              aria-pressed={d.intimacy === x}
              onClick={() => setD({ ...d, intimacy: d.intimacy === x ? undefined : x })}
            >
              {t(`cyc2.day.intimacy.${x}` as MessageKey)}
            </button>
          ))}
        </div>

        <Scale
          legend={t('cyc2.day.energy')}
          value={d.energy}
          onChange={(v) => setD({ ...d, energy: v })}
          lowLabel={t('cyc.energyLow')}
          highLabel={t('cyc.energyHigh')}
        />
        <Scale
          legend={t('cyc2.day.pain')}
          value={d.pain}
          onChange={(v) => setD({ ...d, pain: v })}
          lowLabel={t('cyc.painLow')}
          highLabel={t('cyc.painHigh')}
        />

        <Field label={t('cyc2.day.note')}>
          {(p) => (
            <textarea
              {...p}
              rows={3}
              value={d.note ?? ''}
              onChange={(e) => setD({ ...d, note: e.target.value })}
            />
          )}
        </Field>
        <Dictate
          value={d.note ?? ''}
          onChange={(next) => setD({ ...d, note: next })}
          label={t('cyc2.day.note')}
        />

        <button type="button" className="btn btn--block" disabled={saving} onClick={() => void save()}>
          <Icon name="check" size={18} />
          {t('cyc2.day.save')}
        </button>
      </div>
    </Sheet>
  )
}
