import { useMemo } from 'react'
import {
  addMonths,
  eachDayOfInterval,
  endOfMonth,
  format,
  isSameMonth,
  parseISO,
  startOfMonth,
  startOfWeek,
  endOfWeek,
} from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { useI18n } from '@/i18n'
import type { PhaseId, PredictedCycle } from './phases'

/**
 * The month grid.
 *
 * Every day carries at most one phase colour plus, separately, a dot when there
 * is something logged on it. Those are two different facts — "the estimate says
 * fertile" and "I wrote something down" — and merging them into one colour is
 * how a calendar starts lying about which parts are measured.
 *
 * Predicted days are drawn with an outline rather than a fill. It is a small
 * thing and it is the whole honesty of the screen: solid means it happened,
 * outline means the app is guessing.
 */

export interface DayMark {
  phase: PhaseId | null
  predicted: boolean
  logged: boolean
  cycleDay: number | null
}

export function marksFor(
  cycles: PredictedCycle[],
  loggedDates: Set<string>,
): Map<string, DayMark> {
  const out = new Map<string, DayMark>()
  for (const c of cycles) {
    for (const span of c.phases) {
      const days = eachDayOfInterval({ start: parseISO(span.from), end: parseISO(span.to) })
      days.forEach((d, i) => {
        const key = format(d, 'yyyy-MM-dd')
        // A logged cycle always wins over a projected one: if the period
        // actually arrived, the calendar must show that and not the guess.
        const prev = out.get(key)
        if (prev && !prev.predicted && c.predicted) return
        out.set(key, {
          phase: span.id,
          predicted: c.predicted,
          logged: loggedDates.has(key),
          cycleDay: span.dayFrom + i,
        })
      })
    }
  }
  for (const d of loggedDates) {
    const prev = out.get(d)
    out.set(d, prev ? { ...prev, logged: true } : { phase: null, predicted: false, logged: true, cycleDay: null })
  }
  return out
}

export default function CycleCalendar({
  month,
  onMonth,
  marks,
  selected,
  onSelect,
}: {
  /** First of the displayed month. */
  month: Date
  onMonth: (next: Date) => void
  marks: Map<string, DayMark>
  selected: string
  onSelect: (date: string) => void
}) {
  const { t, locale } = useI18n()
  // `toLocaleDateString` wants a BCP-47 tag, not date-fns' locale object.
  const loc = locale === 'en' ? 'en-GB' : 'id-ID'
  const today = format(new Date(), 'yyyy-MM-dd')

  const grid = useMemo(() => {
    // Whole weeks, so the grid is always seven across and never reflows.
    const from = startOfWeek(startOfMonth(month), { weekStartsOn: 1 })
    const to = endOfWeek(endOfMonth(month), { weekStartsOn: 1 })
    return eachDayOfInterval({ start: from, end: to })
  }, [month])

  const weekdays = useMemo(() => {
    const from = startOfWeek(new Date(), { weekStartsOn: 1 })
    return Array.from({ length: 7 }, (_, i) =>
      new Date(from.getTime() + i * 86_400_000).toLocaleDateString(loc, { weekday: 'narrow' }),
    )
  }, [loc])

  return (
    <div className="cyccal">
      <div className="cyccal__head">
        <button
          type="button"
          className="cyccal__step"
          aria-label={t('cyc2.cal.prev')}
          onClick={() => onMonth(addMonths(month, -1))}
        >
          <Icon name="chevron-left" size={18} />
        </button>
        <strong>{month.toLocaleDateString(loc, { month: 'long', year: 'numeric' })}</strong>
        <button
          type="button"
          className="cyccal__step"
          aria-label={t('cyc2.cal.next')}
          onClick={() => onMonth(addMonths(month, 1))}
        >
          <Icon name="chevron-right" size={18} />
        </button>
      </div>

      <div className="cyccal__weekdays" aria-hidden="true">
        {weekdays.map((d, i) => (
          <span key={i}>{d}</span>
        ))}
      </div>

      {/* A group of buttons, not `role="grid"`. A real grid owes ARIA a row
          per week and arrow-key navigation between cells; claiming the role
          without them makes it *worse* for a screen reader than plain buttons,
          each of which already announces its full date and phase. */}
      <div className="cyccal__grid" role="group" aria-label={t('cyc2.cal.title')}>
        {grid.map((d) => {
          const key = format(d, 'yyyy-MM-dd')
          const m = marks.get(key)
          const outside = !isSameMonth(d, month)
          const classes = [
            'cyccal__day',
            outside ? 'cyccal__day--out' : '',
            m?.phase ? `cyccal__day--${m.phase}` : '',
            m?.predicted ? 'cyccal__day--pred' : '',
            key === today ? 'cyccal__day--today' : '',
            key === selected ? 'cyccal__day--sel' : '',
          ]
            .filter(Boolean)
            .join(' ')
          // The accessible name carries what the colour says, because a colour
          // is not information to everyone.
          const phaseName = m?.phase ? t(`cyc2.phase.${m.phase}`) : ''
          const label = [
            d.toLocaleDateString(loc, { day: 'numeric', month: 'long' }),
            phaseName && (m?.predicted ? `${phaseName} (${t('cyc2.cal.legendPredicted')})` : phaseName),
            m?.cycleDay ? t('cyc2.cal.dayLabel', { n: m.cycleDay }) : '',
            m?.logged ? t('cyc2.cal.legendLogged') : '',
          ]
            .filter(Boolean)
            .join(', ')
          return (
            <button
              key={key}
              type="button"
              className={classes}
              aria-label={label}
              aria-pressed={key === selected}
              onClick={() => onSelect(key)}
            >
              <span className="cyccal__n">{d.getDate()}</span>
              {m?.logged && <i className="cyccal__dot" aria-hidden="true" />}
            </button>
          )
        })}
      </div>

      <ul className="cyccal__legend">
        <li>
          <i className="cyccal__key cyccal__key--menstruasi" /> {t('cyc2.cal.legendPeriod')}
        </li>
        <li>
          <i className="cyccal__key cyccal__key--menstruasi cyccal__key--pred" />{' '}
          {t('cyc2.cal.legendPredicted')}
        </li>
        <li>
          <i className="cyccal__key cyccal__key--ovulasi" /> {t('cyc2.cal.legendFertile')}
        </li>
        <li>
          <i className="cyccal__key cyccal__key--dot" /> {t('cyc2.cal.legendLogged')}
        </li>
      </ul>
    </div>
  )
}
